<script lang="ts">
  import type {Row} from '#lib/client/types.ts';
  import {display,command} from '#lib/client/api.ts';
  import {refreshAll} from '$app/navigation';
  import Icon from '../Icon.svelte';
  import Status from '../Status.svelte';
  import {reportQuantity} from '#lib/client/reports.ts';
  let {issues,definitions,recommendations=[],canWrite=false,from='',to='',business='',timeRows=[],conflicts,corrections,period}:{issues:Row[];definitions:Row[];recommendations?:Row[];canWrite?:boolean;from?:string;to?:string;business?:string;timeRows?:Row[];conflicts?:unknown;corrections?:unknown;period?:Row}=$props();
  let editing=$state('');let reason=$state('');let outcome=$state('done');let busy=$state(false);let error=$state('');let notice=$state('');
  const outcomes:Record<string,string>={done:'Erledigt',deferred:'Zurückgestellt',not_applicable:'Nicht zutreffend'};
  async function feedback(event:SubmitEvent,recommendation:Row){event.preventDefault();if(busy||!recommendation.id||!recommendation.version)return;error='';notice='';busy=true;try{await command('reports.recommendation.feedback',recommendation.id,{outcome,reason,...(from?{from}:{}),...(to?{to}:{}),...(business?{business_unit:business}:{})},recommendation.version);notice='Ihre Rückmeldung wurde mit Begründung gespeichert.';editing='';reason='';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Rückmeldung konnte nicht gespeichert werden.';}finally{busy=false;}}
  function text(value:unknown){return Array.isArray(value)?value.map(item=>typeof item==='string'?item:item.name||item.label||item.table||'Quelle').join(', '):typeof value==='object'&&value!==null?Object.entries(value).map(([key,item])=>`${key}: ${String(item)}`).join(' · '):String(value||'Noch nicht im Register bestätigt');}
</script>
{#if timeRows.length||conflicts!==undefined||corrections!==undefined}<section class="panel mb"><header class="panel-header"><div><h2>Zeitgrundlagen & offene Klärungen</h2><p>{period?.from&&period?.to?`${display(period.from,'date')} bis ${display(period.to,'date')}`:'Ausgewiesenes Kapazitätsfenster'} · Fehlende Abgaben sind keine Nullstunden.</p></div></header><div class="panel-body"><dl class="definition-list"><div><dt>Offene Synchronisationskonflikte</dt><dd>{reportQuantity(conflicts)}</dd></div><div><dt>Noch nicht entschiedene Korrekturen</dt><dd>{reportQuantity(corrections)}</dd></div></dl><p class="field-help mt">Gemeldete Arbeitstage berücksichtigen eingereichte oder genehmigte Zeitabgaben und bestätigte vollständige Abwesenheit. Offene Korrekturen können den Stand noch verändern.</p></div>{#if timeRows.length}<details class="panel-body" style="padding-top:0"><summary class="text-link" style="cursor:pointer">Vollständigkeit je Arbeitstag ansehen</summary><div class="table-scroll mt"><table class="data-table"><caption class="sr-only">Bestätigte erwartete und gemeldete Arbeitstage, fehlende Berechnungsgrundlagen gesondert</caption><thead><tr><th>Tag</th><th class="number">Erwartete Personentage</th><th class="number">Gemeldet / begründet</th><th>Grundlagen</th></tr></thead><tbody>{#each timeRows as row}<tr><th scope="row">{display(row.day,'date')}</th><td class="number">{reportQuantity(row.expected_days)}{Number(row.missing_basis)>0?' bekannte':''}</td><td class="number">{reportQuantity(row.reported_days)}</td><td>{Number(row.missing_basis)>0?`${row.missing_basis} nicht vollständig bestätigte Grundlagen`:'Arbeitsmodelle und Kalender bestätigt'}</td></tr>{/each}</tbody></table></div></details>{/if}</section>{/if}
<section class="panel"><header class="panel-header"><div><h2>Datenlücken zuerst klären</h2><p>Prüfbare Grundlagen statt einer scheinbar genauen Gesamtsumme.</p></div><span class="count">{issues.length} Hinweise</span></header><div class="panel-body">{#each issues as issue}<article class="quality-issue"><div class="quality-icon"><Icon name="alert" size={18}/></div><div><h3>{issue.title||issue.metric_name||'Berechnungsgrundlage ergänzen'}</h3><p>{issue.description||issue.message||'Die betreffende Kennzahl ist noch nicht vollständig belegt.'}</p>{#if issue.affected_metric||issue.metric_key}<p class="field-help">Betroffene Kennzahl: {definitions.find(item=>item.key===(issue.affected_metric||issue.metric_key))?.name||definitions.find(item=>item.key===(issue.affected_metric||issue.metric_key))?.label||'Im Kennzahlenregister beschrieben'}</p>{/if}{#if issue.count!==null&&issue.count!==undefined}<p class="field-help">{issue.count} betroffene Vorgänge</p>{/if}{#if issue.href}<a class="btn small mt" href={issue.href}>Grundlage prüfen<Icon name="arrow" size={14}/></a>{/if}</div><Status value={issue.status||'needs_review'}/></article>{/each}{#if !issues.length}<div class="empty-state compact"><Icon name="check" size={27}/><h3>Keine gemeldeten Prüffälle</h3><p>Eine leere Prüfliste bestätigt noch keine vollständige betriebswirtschaftliche Datengrundlage. Fehlende Restschätzungen und unbestätigte Werte bleiben in den jeweiligen Ansichten sichtbar.</p></div>{/if}</div></section>
{#if recommendations.length}<section class="panel mt"><header class="panel-header"><div><h2>Begründete nächste Schritte</h2><p>Ein Vorschlag erhält erst durch Ihre ausdrückliche Freigabe eine betriebliche Wirkung.</p></div></header><div class="panel-body">{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}{#each recommendations as recommendation}<article class="recommendation"><h3>{recommendation.title||'Prüfvorschlag'}</h3><p>{recommendation.reason||recommendation.description}</p><dl class="definition-list mt"><div><dt>Datenstand</dt><dd>{display(recommendation.as_of||recommendation.data_as_of,'updated_at')}</dd></div><div><dt>Quellen</dt><dd>{text(recommendation.sources)}</dd></div><div class="full"><dt>Annahmen</dt><dd>{text(recommendation.assumptions)}</dd></div></dl>{#if recommendation.href}<a class="btn mt" href={recommendation.href}>{recommendation.action_label||'Grundlage und erlaubten Schritt prüfen'}<Icon name="arrow" size={15}/></a>{/if}{#if recommendation.outcome}<p class="field-help mt">Gespeicherte Rückmeldung: {outcomes[recommendation.outcome]||'Dokumentiert'}{#if recommendation.feedback_reason}<br/>Begründung: {recommendation.feedback_reason}{/if}</p>{/if}{#if canWrite&&recommendation.id&&recommendation.version}{#if editing===recommendation.id}<form class="mt" onsubmit={(event)=>feedback(event,recommendation)}><div class="field-grid"><div class="field"><label for={`recommendation-outcome-${recommendation.id}`}>Ihre Rückmeldung *</label><select id={`recommendation-outcome-${recommendation.id}`} bind:value={outcome} required>{#each Object.entries(outcomes) as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="field full"><label for={`recommendation-reason-${recommendation.id}`}>Begründung *</label><textarea id={`recommendation-reason-${recommendation.id}`} bind:value={reason} required minlength="5" placeholder="Was wurde erledigt oder weshalb trifft der Hinweis nicht zu?"></textarea><span class="field-help">Die Rückmeldung wird nachvollziehbar gespeichert. Sie wird nicht als stilles KI-Training verwendet.</span></div></div><div class="inline-actions mt"><button type="submit" class="btn primary" disabled={busy}>{busy?'Wird gespeichert …':'Rückmeldung speichern'}</button><button type="button" class="btn" disabled={busy} onclick={()=>editing=''}>Abbrechen</button></div></form>{:else}<button class="btn small mt" onclick={()=>{editing=recommendation.id;outcome=recommendation.outcome||'done';reason='';error='';notice='';}}>Rückmeldung geben</button>{/if}{/if}</article>{/each}</div></section>{/if}
<section class="panel mt"><header class="panel-header"><div><h2>Kennzahlen nachvollziehen</h2><p>Definition, Berechnungsregel und Quellen bleiben je Version prüfbar.</p></div></header><div class="panel-body">{#each definitions as definition}<details class="metric-definition"><summary><span>{definition.name||definition.label||definition.key}</span><small>Version {definition.definition_version||definition.version||'nicht bestätigt'}</small></summary><p class="small mt">{definition.description||definition.definition||'Beschreibung noch nicht bestätigt'}</p><dl class="definition-list mt"><div class="full"><dt>Berechnung</dt><dd>{text(definition.formula||definition.calculation_rule||definition.calculation)}</dd></div><div><dt>Einheit</dt><dd>{({EUR:'EUR',currency:'Je ausgewiesener Währung',percent:'Prozent',hours:'Stunden'} as Record<string,string>)[definition.unit]||definition.unit||'Noch nicht bestätigt'}</dd></div><div><dt>Zeitbezug</dt><dd>{text(definition.time_basis||definition.timeBasis)}</dd></div><div class="full"><dt>Einbezogene Zustände</dt><dd>{text(definition.included_states||definition.includedStates)}</dd></div><div class="full"><dt>Ausgeschlossene Zustände</dt><dd>{text(definition.excluded_states||definition.excludedStates)}</dd></div><div class="full"><dt>Quellen</dt><dd>{text(definition.sources||definition.data_sources)}</dd></div></dl>{#if definition.href}<a class="text-link mt" href={definition.href}>Ursprungsbelege öffnen<Icon name="arrow" size={14}/></a>{/if}</details>{/each}{#if !definitions.length}<p class="small">Noch kein Kennzahlenregister freigegeben. Bestätigte Beauftragungen, ausgestellte Rechnungen, tatsächliche Zahlungen und bewertete Leistung werden fachlich getrennt betrachtet.</p>{/if}</div></section>
<style>.quality-issue{display:flex;gap:15px;align-items:flex-start}.quality-issue+.quality-issue{border-top:1px solid var(--line);padding-top:24px;margin-top:24px}.quality-issue>div:nth-child(2){flex:1;min-width:0}.quality-icon{color:var(--warning);padding-top:2px}.quality-issue h3,.recommendation h3{font-size:14px;font-weight:550;line-height:1.5}.quality-issue p,.recommendation>p{font-size:12px;margin-top:6px}.quality-issue .field-help{font-size:11px}.metric-definition+.metric-definition{border-top:1px solid var(--line);padding-top:19px;margin-top:19px}.metric-definition summary{display:flex;justify-content:space-between;align-items:center;gap:15px;font-size:13px;font-weight:500;cursor:pointer;list-style-position:inside;min-height:32px}.metric-definition summary small{font-size:11px;color:var(--muted);font-weight:400}.metric-definition dd{font-size:12px;overflow-wrap:anywhere}.recommendation+.recommendation{border-top:1px solid var(--line);padding-top:25px;margin-top:25px}@media(max-width:760px){.quality-issue{flex-wrap:wrap;gap:10px}.quality-issue :global(.status){margin-left:28px}.quality-issue h3,.recommendation h3{font-size:15px}.quality-issue p,.recommendation>p{font-size:13px}.quality-issue .field-help{font-size:12px}.metric-definition summary{font-size:14px;align-items:flex-start;min-height:48px}.metric-definition summary small{font-size:12px;max-width:100px;text-align:right}.metric-definition dd{font-size:13px}}</style>
